72	// Choose a vector width for non-fragment SIMT loops while keeping the full
73	// thread extent active.  The loop partitioner covers work in chunks of
74	// `thread_extent * vector_size`; when the logical loop size is ragged, the
75	// excess points are guarded as padding.  Prefer the candidate that introduces
76	// the fewest padded points, and keep the wider vector width on ties.
77	int SelectMinPaddingVectorSize(int max_vector_size, PrimExpr loop_total_size,
78	                               PrimExpr thread_extent,
79	                               arith::Analyzer *analyzer) {
80	  ICHECK_GT(max_vector_size, 0);
81	  const int64_t *total = as_const_int(analyzer->Simplify(loop_total_size));
82	  const int64_t *threads = as_const_int(analyzer->Simplify(thread_extent));
83	  // This is a compile-time planning heuristic.  If the size is symbolic, keep
84	  // the vectorizer's original choice and rely on the existing runtime guard.
85	  if (total == nullptr || threads == nullptr || *threads <= 0) {
86	    return max_vector_size;
87	  }
88	
89	  int best_vector_size = max_vector_size;
90	  int64_t best_padding = 0;
91	  bool has_best = false;
92	  PrimExpr total_i64 = cast(DataType::Int(64), loop_total_size);
93	  // Candidate vector widths are generated by halving the maximum legal width,
94	  // matching the rest of the vectorization planner's power-of-two choices.
95	  for (int candidate = max_vector_size; candidate >= 1; candidate /= 2) {
96	    PrimExpr partition_width =
97	        IntImm(DataType::Int(64), (*threads) * static_cast<int64_t>(candidate));
98	    // Use tirx::ceildiv instead of hand-rolled integer arithmetic so the same
99	    // simplification and constant-folding rules are used as TIR expressions.
100	    PrimExpr covered_expr = analyzer->Simplify(
101	        ceildiv(total_i64, partition_width) * partition_width);
102	    const int64_t *covered = as_const_int(covered_expr);
103	    if (covered == nullptr) {
104	      return max_vector_size;
105	    }
106	    int64_t padding = *covered - *total;
107	    if (!has_best || padding < best_padding ||
108	        (padding == best_padding && candidate > best_vector_size)) {
109	      has_best = true;
110	      best_padding = padding;
111	      best_vector_size = candidate;
112	    }
113	    if (candidate == 1) {
114	      break;
115	    }
116	  }
117	  return best_vector_size;
118	}
119	
120	} // anonymous namespace
