122	/**
123	 * @brief Handle a parallel For node during traversal, collecting loop metadata.
124	 *
125	 * Visits a parallel loop, asserts the loop is parallel, records a data-parallel
126	 * IterVar for the loop, binds the loop variable range into the analyzer scope,
127	 * and extracts any reducer information from the loop's annotations into the
128	 * visitor's reducer_info_map_. Continues traversal into the loop body.
129	 */
130	void ParallelLoopNestVisitor::VisitStmt_(const ForNode *op) {
131	  if (op->kind == ForKind::kParallel)
132	    p->loop_vars_.push_back(IterVar(Range(op->min, op->extent), op->loop_var,
133	                                    IterVarType::kDataPar));
134	  else
135	    p->inner_vars_.Set(op->loop_var,
136	                       IterVar(Range(op->min, op->extent), op->loop_var,
137	                               IterVarType::kOrdered));
138	  p->analyzer_.Bind(op->loop_var, Range::FromMinExtent(op->min, op->extent));
139	  if (auto reducer_info_ref = op->annotations.Get(attr::kReducerInfo)) {
140	    if (auto reducer_info_map =
141	            reducer_info_ref.value().as<Map<Var, ReducerInfo>>()) {
142	      for (auto &&[buffer, info] : reducer_info_map.value())
143	        p->reducer_info_map_.Set(buffer, info);
144	    }
145	  }
146	  StmtExprVisitor::VisitStmt_(op);
147	}
