163	ParallelOpNode::ParallelOpNode(For root) : root_(root), V(this) {
164	  V.VisitStmt(root);
165	  // Cache any annotated layout/predicate on the outermost loop.
166	  using namespace attr;
167	  if (root_->annotations.count(kParallelLoopLayout)) {
168	    annotated_layout_unbound_ =
169	        Downcast<Fragment>(root_->annotations.Get(kParallelLoopLayout).value());
170	  }
171	  if (root_->annotations.count(kParallelLoopPredicate)) {
172	    annotated_predicate_ = Downcast<PrimExpr>(
173	        root_->annotations.Get(kParallelLoopPredicate).value());
174	  }
175	  if (auto padding_guard_anno =
176	          root_->annotations.Get(kParallelLoopRequiresPaddingGuard)) {
177	    if (auto padding_guard_bool = padding_guard_anno.value().try_cast<Bool>()) {
178	      annotated_requires_padding_guard_ = padding_guard_bool.value()->value;
179	    } else if (auto padding_guard_int =
180	                   padding_guard_anno.value().as<IntImmNode>()) {
181	      annotated_requires_padding_guard_ = padding_guard_int->value != 0;
182	    } else {
183	      LOG(WARNING) << "Loop annotation `" << kParallelLoopRequiresPaddingGuard
184	                   << "` expects Bool value (True/False), but got "
185	                   << padding_guard_anno.value().GetTypeKey()
186	                   << ". Ignore override.";
187	    }
188	  }
189	  // Collect cross-thread access info and buffer store info.
190	  PostOrderVisit(root_, [&](const ObjectRef &obj) {
191	    if (const auto *store = obj.as<BufferStoreNode>()) {
192	      auto buffer = store->buffer;
193	      if (IsSharedBuffer(buffer) || IsGlobalBuffer(buffer)) {
194	        has_cross_thread_access_ = true;
195	        store_shared_global_buffers_.emplace_back(buffer);
196	      } else if (IsFragmentBuffer(buffer)) {
197	        store_fragment_buffers_.emplace_back(buffer);
198	      }
199	    } else if (const auto *load = obj.as<BufferLoadNode>()) {
200	      if (IsSharedBuffer(load->buffer) || IsGlobalBuffer(load->buffer)) {
201	        has_cross_thread_access_ = true;
202	      }
203	    }
204	  });
205	}
