211	
212	void ParallelOpNode::ExpandBindValues(
213	    const Map<Var, PrimExpr> &bind_var_to_expr) {
214	  if (bind_var_to_expr.empty())
215	    return;
216	
217	  // Helper function to recursively find BufferLoads through Bind values
218	  std::function<void(const PrimExpr &)> expand = [&](const PrimExpr &expr) {
219	    PostOrderVisit(expr, [&](const ObjectRef &node) {
220	      if (auto bl = node.as<BufferLoadNode>()) {
221	        if (IsFragmentBuffer(bl->buffer)) {
222	          RecordBufferAccess(bl->buffer, bl->indices, /*is_write=*/false);
223	        }
224	      } else if (auto var_node = node.as<VarNode>()) {
225	        auto var = GetRef<Var>(var_node);
226	        if (bind_var_to_expr.count(var)) {
227	          expand(bind_var_to_expr[var]);
228	        }
229	      }
230	    });
231	  };
232	
233	  // Only expand Bind values that are used in root_
234	  // First, collect all vars used in root_
235	  std::unordered_set<const VarNode *> used_vars;
236	  PostOrderVisit(root_, [&](const ObjectRef &node) {
237	    if (auto var_node = node.as<VarNode>()) {
238	      used_vars.insert(var_node);
239	    }
240	  });
241	
242	  // Only expand Bind values for vars that are actually used in root_
243	  for (const auto &[var, expr] : bind_var_to_expr) {
244	    if (used_vars.count(var.get())) {
245	      expand(expr);
246	    }
247	  }
248	}
