250	void ParallelOpNode::RecordBufferAccess(const Buffer &buffer,
251	                                        const Array<PrimExpr> &indices,
252	                                        bool is_write) {
253	  auto it = indice_map_.find(buffer);
254	  if (it != indice_map_.end()) {
255	    ICHECK(StructuralEqual()(it->second.indices, indices))
256	        << buffer << ": " << indices << " and " << it->second.indices;
257	  } else {
258	    BufferAccessInfo info;
259	    info.indices = indices;
260	    it = indice_map_.emplace(buffer, std::move(info)).first;
261	    access_order_.push_back(buffer);
262	  }
263	  if (is_write) {
264	    it->second.is_write = true;
265	  } else {
266	    it->second.is_read = true;
267	  }
268	}
