271	ParallelOpNode::GetAccessInfo(const Buffer &buffer) const {
272	  auto it = indice_map_.find(buffer);
273	  ICHECK(it != indice_map_.end())
274	      << "Missing access info for buffer " << buffer;
275	  return it->second;
276	}
