278	bool ParallelOpNode::IsBufferCompletelyReplicated(
279	    const Buffer &buffer, const LayoutMap &layout_map) const {
280	  if (!IsFragmentBuffer(buffer))
281	    return false;
282	  auto frag = layout_map[buffer].as<Fragment>().value();
283	  // buffer indices should be IntImm
284	  for (const auto &index : GetAccessInfo(buffer).indices) {
285	    if (!index.as<IntImmNode>()) {
286	      return false;
287	    } else if (index.as<IntImmNode>()->value != 0) {
288	      LOG(FATAL) << "buffer " << buffer << " is not completed replicated";
289	    }
290	  }
291	  return frag->IsCompletedReplicated();
292	}
