305	
306	/*! \brief Infer the layout for parallel operations based on different inference
307	 * levels
308	 *
309	 * The inference level controls how aggressively we try to infer and optimize
310	 * layouts:
311	 * - kStrict (2): Most conservative level. Only allows explicitly defined
312	 * layouts. Returns empty layout map if loop_layout_ is not already defined.
313	 *                Used when exact layout control is required.
314	 *
315	 * - kCommon (1): Intermediate level between strict and free.
316	 *                Allows common layout patterns while maintaining some
317	 * constraints.
318	 *
319	 * - kFree (0):   Most permissive level. Allows maximum optimization freedom.
320	 *                Will attempt layout inference even without source buffers.
321	 *                Can generate new layouts based on vectorization and thread
322	 * bounds. Used when maximum performance optimization is desired.
323	 */
324	LayoutMap ParallelOpNode::InferLayout(const LayoutInferArgs &layout_args,
325	                                      InferLevel level) const {
326	  if (loop_layout_inferred_)
327	    return {};
328	  loop_layout_requires_padding_guard_ = false;
329	
330	  // Expand Bind values to find fragment buffer accesses
331	  if (!layout_args.bind_var_to_expr.empty()) {
332	    const_cast<ParallelOpNode *>(this)->ExpandBindValues(
333	        layout_args.bind_var_to_expr);
334	  }
335	
336	  if (level == InferLevel::kStrict) {
337	    LayoutMap results;
338	    // Deduce buffers that should be complicated replicated.
339	    // For example:
340	    // for i in T.Parallel(m):
341	    //   fragment[0] = x[i]
342	    // then fragment[0] must be replicated on all threads.
343	    for (const auto &buffer : access_order_) {
344	      const auto &access = GetAccessInfo(buffer);
345	      if (layout_args.layout_map.count(buffer)) {
346	        continue;
347	      }
348	      if (!IsFragmentBuffer(buffer))
349	        continue;
350	
351	      // Check if all indices are zero
352	      bool all_indices_zero = true;
353	      for (const auto &index : access.indices) {
354	        if (const auto *imm = index.as<IntImmNode>()) {
355	          if (imm->value != 0) {
356	            all_indices_zero = false;
357	            LOG(FATAL)
358	                << "Fragment buffer access with non-zero index [" << imm->value
359	                << "] is not supported. "
360	                << "Only fragment[0] access is allowed within T.Parallel loop.";
361	          }
362	        } else {
363	          // Non-constant index, not all zero
364	          all_indices_zero = false;
365	        }
366	      }
367	
368	      // Only set layout if all indices are zero
369	      if (all_indices_zero) {
370	        Array<IterVar> forward_vars;
371	        for (const auto &s : buffer->shape) {
372	          forward_vars.push_back(
373	              IterVar(Range(0, s), Var(), IterVarType::kDataPar));
374	        }
375	        Var rep;
376	        auto rep_iter = IterVar({0, layout_args.thread_bounds->extent}, rep,
377	                                IterVarType::kDataPar);
378	
379	        // Use default fragment indexing (single output dim) to
380	        // stay consistent with other ops (e.g., ReduceOp), and
381	        // bind the thread range for comparability.
382	        const PrimExpr &forward_thread = rep;
383	        auto frag = Fragment(forward_vars, /*forward_index=*/{}, forward_thread,
384	                             rep_iter)
385	                        ->BindThreadRange(layout_args.thread_bounds);
386	        results.Set(buffer, frag);
387	      }
388	    }
389	    return results;
390	  }
391	
392	  // Collect fragment buffers with const index and all fragment_buffers
393	  std::vector<Buffer> const_index_fragment_buffer, fragment_buffers;
394	  for (const auto &buffer : access_order_) {
395	    const auto &access = GetAccessInfo(buffer);
396	    if (!IsFragmentBuffer(buffer))
397	      continue;
398	    fragment_buffers.push_back(buffer);
399	
400	    bool is_const_index = true;
401	    for (const auto &index : access.indices) {
402	      if (!index.as<IntImmNode>()) {
403	        is_const_index = false;
404	        break;
405	      }
406	    }
407	    if (is_const_index) {
408	      const_index_fragment_buffer.push_back(buffer);
409	    }
410	  }
411	
412	  // Determine if common layout propagation should be applied.
413	  // If there are fragment buffers with non-constant indices, we need to
414	  // propagate the common layout pattern to ensure consistency across all
415	  // fragments. Example cases:
416	  //   - Need propagation: frag_a[0] = T.min(frag_a[0], frag_b[i])
417	  //     (const index frag_a interacts with non-const index frag_b)
418	  //   - No propagation needed: shared_a[i] = frag_a[0]
419	  //     (const index frag_a with non-fragment buffer)
420	
421	  bool allow_layout_propgate =
422	      const_index_fragment_buffer.empty() ||
423	      (fragment_buffers.size() > const_index_fragment_buffer.size());
424	
425	  // Step 1: try to infer loop's partition from a source fragment
426	  Buffer source_buffer, read_source_buffer;
427	  bool source_buffer_is_write = false;
428	  Buffer replicated_write_buffer; // Backup: fully replicated write buffer
429	
430	  for (const auto &buffer : access_order_) {
431	    const auto &access = GetAccessInfo(buffer);
432	    if (layout_args.layout_map.count(buffer)) {
433	      // skip reducers with rep=ALL
434	      if (auto info = reducer_info_map_.Get(buffer->data);
435	          info && info.value()->rep == ReducerRepType::ALL)
436	        continue;
437	
438	      bool is_fully_replicated =
439	          IsBufferCompletelyReplicated(buffer, layout_args.layout_map);
440	
441	      if (access.is_write) {
442	        source_buffer = buffer;
443	        source_buffer_is_write = true;
444	      } else {
445	        // Keep the buffer with largest number of indices
446	        // (which means the inference based on that buffer is more accurate)
447	        // as read_source_buffer to get more accurate layout
448	        // if the buffer is completed replicated, we don't need to infer the
449	        // layout from this buffer.
450	        if ((!read_source_buffer.defined() ||
451	             access.indices.size() >
452	                 GetAccessInfo(read_source_buffer).indices.size())) {
453	          read_source_buffer = buffer;
454	        }
455	        // If the buffer is not replicated and shape is equal to the
456	        // source_buffer, use it as source_buffer because the layout inference
457	        // is more accurate
458	        auto frag = layout_args.layout_map[buffer].as<Fragment>();
459	        if (frag.has_value() && is_one(frag.value()->ReplicateExtent()) &&
460	            !source_buffer.defined()) {
461	          source_buffer = buffer;
462	          source_buffer_is_write = false;
463	        }
464	      }
465	    }
466	  }
467	  // moved to ComputeLoopLayoutFromBuffer
468	
469	  // Try to infer loop layout from buffers in order of preference only if we
470	  // don't already have a layout (e.g., from annotations):
471	  // 1. Annotated loop layout
472	  // 2. Non-replicated write buffer (most reliable)
473	  // 3. Non-replicated read buffer
474	  // 4. Fully replicated write buffer (backup, may cause issues)
475	  // 5. Free inference mode (no source buffer)
476	  if (!loop_layout_.defined() && annotated_layout_unbound_.defined()) {
477	    loop_layout_ = annotated_layout_unbound_.value()->BindThreadRange(
478	        layout_args.thread_bounds);
479	    loop_layout_requires_padding_guard_ = annotated_requires_padding_guard_;
480	    if (annotated_predicate_.defined()) {
481	      predicate_ = annotated_predicate_.value();
482	    }
483	  } else if (!loop_layout_.defined() && source_buffer.defined() &&
484	             (allow_layout_propgate || source_buffer_is_write)) {
485	    loop_layout_ = ComputeLoopLayoutFromBuffer(source_buffer, layout_args);
486	  } else if (!loop_layout_.defined() && level == InferLevel::kFree) {
487	    // For free layout inference
488	    // In free inference, try two mechanisms and prefer the one that
489	    // minimizes replication while remaining compatible:
490	    // 1) compute_loop_layout_from_buffer (always correct but may
491	    // over-replicate) 2) PlanLoopPartition (often smaller replication)
492	    Fragment candidate_from_buffer;
493	    Fragment candidate_from_plan;
494	    bool selected_plan_candidate = false;
495	
496	    if (read_source_buffer.defined() && allow_layout_propgate) {
497	      candidate_from_buffer =
498	          ComputeLoopLayoutFromBuffer(read_source_buffer, layout_args);
499	    }
500	
501	    // try to infer loop layout with two mechanisms and choose the best one
502	    {
503	      candidate_from_plan = ComputePlanCandidate(layout_args);
504	    }
505	
506	    // Choose the best candidate:
507	    if (candidate_from_buffer.defined() && candidate_from_plan.defined()) {
508	      loop_layout_ = ChooseBestCandidate(candidate_from_buffer,
509	                                         candidate_from_plan, layout_args);
510	    } else if (candidate_from_plan.defined()) {
511	      loop_layout_ = candidate_from_plan;
512	      selected_plan_candidate = true;
513	      DLOG(INFO) << "[FreeInfer] only PlanLoopPartition available, choose it.";
514	    } else if (candidate_from_buffer.defined()) {
515	      loop_layout_ = candidate_from_buffer;
516	      DLOG(INFO)
517	          << "[FreeInfer] only compute_from_buffer available, choose it.";
518	    }
519	    loop_layout_requires_padding_guard_ =
520	        selected_plan_candidate && indice_map_.empty();
521	  } else if (!loop_layout_.defined()) {
522	    // In non-free mode without a source buffer, if we don't have any layout
523	    // yet (e.g., no annotation), we have nothing to infer here.
524	    return {};
525	  }
526	
527	  // Non-fragment SIMT loops may deliberately over-cover a ragged iteration
528	  // space; PartitionLoop emits guards for the padded points. Fragment/reducer
529	  // loops stay strict because padding would change per-thread ownership.
530	  auto injective_res =
531	      loop_layout_->DetectInjective(loop_layout_requires_padding_guard_);
532	  if (!injective_res->errors.empty()) {
533	    std::ostringstream oss;
534	    oss << "Loop layout is not injective: " << loop_layout_->DebugOutput()
535	        << '\n'
536	        << "  errors: " << injective_res->errors << '\n'
537	        << "  loop AST: " << root_;
538	    throw LoopLayoutInjectiveException(oss.str());
539	  }
540	
541	  PrimExpr loop_thread_extent = loop_layout_->ThreadExtent();
542	
543	  auto block_size = layout_args.thread_bounds->extent;
544	  if (loop_layout_.defined()) {
545	    if (loop_layout_->ThreadRange().defined()) {
546	      auto thread_range = loop_layout_->ThreadRange();
547	      block_size = thread_range->extent;
548	      AddPredicate(GE(InputPlaceholder(0), thread_range->min));
549	      AddPredicate(
550	          LT(InputPlaceholder(0), thread_range->min + thread_range->extent));
551	    }
552	  }
553	
554	  if (!analyzer_.CanProveEqual(loop_thread_extent, block_size)) {
555	    AddPredicate(LT(InputPlaceholder(0),
556	                    loop_thread_extent + layout_args.thread_bounds->min));
557	  }
558	
559	  // Step 2: Check that the loop's partition can correctly align with all source
560	  // fragment, and infer layout only when it's not yet layout-ed.
561	  ValidateCandidateAgainstFragments(
562	      loop_layout_, layout_args, /*throw_on_error=*/true,
563	      /*check_forward_index=*/false, source_buffer);
564	
565	  // Step 3: Build replication guards
566	  BuildReplicationGuardsIfNeeded(
567	      layout_args, store_shared_global_buffers_, store_fragment_buffers_,
568	      has_cross_thread_access_, const_index_fragment_buffer);
569	
570	  // Step 4: Collect buffer fragments
571	  LayoutMap results;
572	  for (const auto &buffer : access_order_) {
573	    if (!layout_args.layout_map.count(buffer)) {
574	      auto dst_layout = CompleteBufferFragment(buffer)->BindThreadRange(
575	          layout_args.thread_bounds);
576	      results.Set(buffer, dst_layout);
577	    }
578	  }
579	  loop_layout_inferred_ = true;
580	  return results;
581	}
