583	Optional<PrimExpr> ParallelOpNode::GetPredicate(PrimExpr thread_index) const {
584	  if (predicate_.defined()) {
585	    return Substitute(predicate_.value(),
586	                      {{InputPlaceholder(0), thread_index}});
587	  } else {
588	    return std::nullopt;
589	  }
