591	
592	Fragment ParallelOpNode::CompleteBufferFragment(const Buffer &buffer) const {
593	  ICHECK(loop_layout_.defined());
594	  if (IsCommonAccessIndice(buffer)) {
595	    return loop_layout_;
596	  }
597	  // Prefer a simple path: if original 2D indices form a bijective map, invert
598	  // them directly and avoid introducing a synthetic replicate dimension.
599	  {
600	    auto res2d =
601	        arith::DetectIterMap(GetAccessInfo(buffer).indices, ToVMap(loop_vars_),
602	                             1, arith::IterMapLevel::Bijective,
603	                             const_cast<arith::Analyzer *>(&analyzer_));
604	    if (res2d->errors.empty()) {
605	      Layout ind_inv2d =
606	          Layout(loop_vars_, GetAccessInfo(buffer).indices)->Inverse();
607	      PrimExpr indice_rep_extent = 1;
608	      PrimExpr loop_rep_extent = loop_layout_->ReplicateExtent();
609	      PrimExpr dest_buffer_rep_extent = indice_rep_extent * loop_rep_extent;
610	      Array<PrimExpr> fwd2;
611	      for (size_t i = 0; i < buffer->shape.size(); i++) {
612	        fwd2.push_back(InputPlaceholder(i));
613	      }
614	      PrimExpr thd_b2 =
615	          loop_layout_->ForwardThread(ind_inv2d->Forward(fwd2), std::nullopt);
616	      return Fragment(buffer->shape, {}, thd_b2, dest_buffer_rep_extent,
617	                      std::nullopt)
618	          ->CondenseReplicateVar();
619	    }
620	  }
621	  // Otherwise, infer an extra flattened iterator that captures truly-unused
622	  // pieces of the loop space (if any), then try inversion with it.
623	  PrimExpr rep_b = MakeFlattenedExpression(DivideUnusedIterators(
624	      GetAccessInfo(buffer).indices, loop_vars_, &analyzer_));
625	  auto bijective_indice = GetAccessInfo(buffer).indices;
626	  bijective_indice.push_back(rep_b);
627	  Layout ind_inv = Layout(loop_vars_, bijective_indice)->Inverse();
628	
629	  PrimExpr indice_rep_extent =
630	      ind_inv->InputShape().back(); // this is the size of rep_b
631	  PrimExpr loop_rep_extent = loop_layout_->ReplicateExtent();
632	  PrimExpr dest_buffer_rep_extent = indice_rep_extent * loop_rep_extent;
633	  Array<PrimExpr> fwd;
634	  for (size_t i = 0; i < buffer->shape.size(); i++) {
635	    fwd.push_back(InputPlaceholder(i));
636	  }
637	  fwd.push_back(FloorMod(ReplicationPlaceholder(), indice_rep_extent));
638	  PrimExpr thd_b = loop_layout_->ForwardThread(
639	      ind_inv->Forward(fwd),
640	      FloorDiv(ReplicationPlaceholder(), indice_rep_extent));
641	  return Fragment(buffer->shape, {}, thd_b, dest_buffer_rep_extent,
642	                  std::nullopt)
643	      ->CondenseReplicateVar();
644	}
