647	
648	bool ParallelOpNode::ValidateCandidateAgainstFragments(
649	    const Fragment &candidate, const LayoutInferArgs &layout_args,
650	    bool throw_on_error, bool check_forward_index,
651	    const Buffer &source_buffer) const {
652	  auto vars =
653	      loop_vars_.Map([](const IterVar &iv) { return PrimExpr(iv->var); });
654	  for (const auto &buffer : access_order_) {
655	    const auto &access = GetAccessInfo(buffer);
656	    if (!layout_args.layout_map.count(buffer))
657	      continue;
658	    if (auto info = reducer_info_map_.Get(buffer->data);
659	        info && info.value()->rep == ReducerRepType::ALL)
660	      continue;
661	    auto fragment = layout_args.layout_map[buffer].as<Fragment>().value();
662	    std::ostringstream oss;
663	    bool success = true;
664	    if (access.is_read &&
665	        !ProveFragmentContains(candidate, fragment, vars, access.indices,
666	                               analyzer_, check_forward_index)) {
667	      if (throw_on_error) {
668	        oss << "Layout infer conflict between " << buffer << " and "
669	            << source_buffer << " in T.Parallel loop:" << '\n'
670	            << "    loop " << candidate->DebugOutput() << '\n'
671	            << "    fragment " << fragment->DebugOutput() << '\n';
672	      }
673	      success = false;
674	    }
675	    // Fragment writes need exact owner-thread compatibility. Coverage alone
676	    // allows extra loop threads to write local slots that belong to different
677	    // logical fragment elements under the buffer layout.
678	    if (access.is_write &&
679	        (!ProveFragmentContains(fragment, candidate, access.indices, vars,
680	                                analyzer_, check_forward_index) ||
681	         !ProveFragmentContains(candidate, fragment, vars, access.indices,
682	                                analyzer_, check_forward_index))) {
683	      if (throw_on_error) {
684	        oss << "Layout infer conflict between " << buffer << " and "
685	            << source_buffer << " in T.Parallel loop:" << '\n'
686	            << "    loop " << candidate->DebugOutput() << '\n'
687	            << "    fragment " << fragment->DebugOutput() << '\n';
688	      }
689	      success = false;
690	    }
691	    if (!success) {
692	      if (throw_on_error) {
693	        throw LayoutConflictException(oss.str());
694	      }
695	      return false;
696	    }
697	  }
698	  return true;
699	}
700	
701	Fragment ParallelOpNode::ComputeLoopLayoutFromBuffer(
702	    const Buffer &buffer, const LayoutInferArgs &layout_args) const {
703	  Fragment src_layout = layout_args.layout_map[buffer].as<Fragment>().value();
704	  DLOG(INFO) << "[compute_loop_layout_from_buffer] infer from buffer `"
705	             << buffer << "` of layout " << src_layout->DebugOutput() << '\n';
706	
707	  Fragment result;
708	
709	  if (IsCommonAccessIndice(buffer)) {
710	    result = src_layout;
711	  } else {
712	    Var rep("_rep");
713	    auto rep_iter =
714	        IterVar({0, src_layout->ReplicateExtent()}, rep, IterVarType::kDataPar);
715	    PrimExpr loop_var_to_thread =
716	        src_layout->ForwardThread(GetAccessInfo(buffer).indices, rep);
717	    loop_var_to_thread = analyzer_.Simplify(loop_var_to_thread);
718	    PostOrderVisit(loop_var_to_thread, [&](const ObjectRef &objref) {
719	      if (auto opt_var = objref.as<Var>();
720	          opt_var && inner_vars_.count(*opt_var)) {
721	        std::ostringstream oss;
722	        oss << "Cannot lower access to thread-distributed fragment `"
723	            << buffer->name
724	            << "`: its elements are spread across CUDA threads, so the "
725	               "non-parallel loop variable `"
726	            << *opt_var
727	            << "` cannot be used to address them safely (thread map: "
728	            << loop_var_to_thread
729	            << "). Use T.reduce_sum for reductions, T.Parallel for elementwise "
730	               "access, or stage through shared memory to change the layout.";
731	        throw LayoutConflictException(oss.str());
732	      }
733	    });
734	
735	    try {
736	      result = Fragment(loop_vars_, {}, loop_var_to_thread, rep_iter)
737	                   ->BindThreadRange(layout_args.thread_bounds);
738	    } catch (const Error &err) {
739	      std::ostringstream msg;
740	      msg << "Layout inference for buffer `" << buffer->name
741	          << "` failed inside `T.parallel` loop.";
742	
743	      msg << "\nUnderlying TVM error: " << err.what();
744	      msg << "\nProblematic loop AST:\n " << root_;
745	      msg << "\nHint: ensure the loop extent divides the thread binding or "
746	             "adjust the fragment mapping.";
747	      LOG(FATAL) << msg.str();
748	    }
749	  }
750	  DLOG(INFO) << "[compute_loop_layout_from_buffer] ... and get "
751	             << result->DebugOutput() << '\n';
752	  // Lei: This is a tradeoff, disable it for now.
753	  // // Try DeReplicate first to reduce replication if possible.
754	  // Fragment dereplicated_layout = candidate_from_buffer->DeReplicate();
755	  // if (ValidateCandidateAgainstFragments(
756	  //         dereplicated_layout, T, /*throw_on_error=*/false,
757	  //         /*check_forward_index=*/false,
758	  //         /*source_buffer=*/read_source_buffer)) {
759	  //   candidate_from_buffer = dereplicated_layout;
760	  // }
761	  return result;
762	}
763	
764	Fragment
765	ParallelOpNode::ComputePlanCandidate(const LayoutInferArgs &layout_args) const {
766	  // Vectorize Size must be aware of the buffer_remap
767	  // As the pass will do post processing to the layout
768	  auto maybe_remapped_root_ = IfBufferRemapLoopGenerator::run(
769	      root_, layout_args.buffer_remap, layout_args.layout_map);
770	  int vector_size = GetVectorizeSize(maybe_remapped_root_, layout_args.analyzer,
771	                                     layout_args.layout_map, reducer_info_map_);
772	  DLOG(INFO) << "[PlanLoopPartition] vector_size = " << vector_size << '\n';
773	
774	  PrimExpr loop_total_size = 1;
775	  for (Stmt l = root_; l.as<For>().has_value(); l = l.as<For>().value()->body)
776	    loop_total_size = loop_total_size * l.as<For>().value()->extent;
777	  DLOG(INFO) << "[PlanLoopPartition] loop_total_size = " << loop_total_size
778	             << '\n';
779	  bool has_fragment_access = !indice_map_.empty();
780	  if (has_fragment_access) {
781	    while (!analyzer_.CanProve(
782	               floormod(loop_total_size, layout_args.thread_bounds->extent *
783	                                             vector_size) == 0) &&
784	           vector_size > 1) {
785	      vector_size /= 2;
786	    }
787	  } else if (!root_->annotations.count(attr::kCoalescedWidth)) {
788	    vector_size = SelectMinPaddingVectorSize(vector_size, loop_total_size,
789	                                             layout_args.thread_bounds->extent,
790	                                             &analyzer_);
791	  }
792	  DLOG(INFO) << "[PlanLoopPartition] after adjust: vector_size = "
793	             << vector_size << '\n';
794	
795	  // Check if coalesced_width is defined
796	  if (auto coalesced_width = root_->annotations.Get(attr::kCoalescedWidth)) {
797	    if (const auto *imm = coalesced_width->as<IntImmNode>()) {
798	      int expected = imm->value;
799	      // Verify that vector_size is divisible by expected
800	      if (vector_size % expected != 0) {
801	        LOG(FATAL) << "Vector size " << vector_size
802	                   << " is not divisible by coalesced width " << expected;
803	      }
804	      vector_size = expected;
805	    } else {
806	      LOG(FATAL) << "coalesced_width should be an IntImmNode.";
807	    }
808	  }
809	  DLOG(INFO) << "[PlanLoopPartition] root_ = " << root_
810	             << " ############# vector_size = " << vector_size
811	             << ", thread_bounds = " << layout_args.thread_bounds << '\n';
812	  auto plan = PlanLoopPartition(root_, vector_size, layout_args.thread_bounds);
813	  DLOG(INFO) << "[PlanLoopPartition] candidate = " << plan->DebugOutput()
814	             << '\n';
815	  return plan;
816	}
817	
818	void ParallelOpNode::BuildReplicationGuardsIfNeeded(
819	    const LayoutInferArgs &layout_args,
820	    const std::vector<Buffer> &store_shared_global_buffers,
821	    const std::vector<Buffer> &store_fragment_buffers,
822	    bool has_cross_thread_access,
823	    const std::vector<Buffer> &const_index_fragment_buffer) const {
824	  if (is_one(loop_layout_->ReplicateExtent()))
825	    return;
826	  if (!has_cross_thread_access)
827	    return;
828	
829	  if (!store_fragment_buffers.empty()) {
830	    bool replicate_is_from_dynamic_index_fragment = false;
831	    for (const auto &fragment : store_fragment_buffers) {
832	      if (!layout_args.layout_map.count(fragment)) {
833	        continue;
834	      }
835	
836	      auto fragment_layout =
837	          layout_args.layout_map[fragment].as<Fragment>().value();
838	      if (is_one(fragment_layout->ReplicateExtent()))
839	        continue;
840	
841	      if (analyzer_.CanProveEqual(fragment_layout->ReplicateExtent(),
842	                                  loop_layout_->ReplicateExtent()))
843	        continue;
844	      if (std::find(const_index_fragment_buffer.begin(),
845	                    const_index_fragment_buffer.end(),
846	                    fragment) == const_index_fragment_buffer.end()) {
847	        replicate_is_from_dynamic_index_fragment = true;
848	      }
849	    }
850	
851	    if (!replicate_is_from_dynamic_index_fragment)
852	      return;
853	
854	    ICHECK(store_shared_global_buffers.empty())
855	        << "Invalid layout: cannot have both fragment and shared store buffers "
856	           "in replicated loop layout.";
857	    return;
858	  } else {
859	    auto inv = loop_layout_->Inverse();
860	    Array<PrimExpr> fwd;
861	    for (size_t i = 0; i < loop_layout_->OutputDim(); i++)
862	      fwd.push_back(0);
863	    fwd.push_back(InputPlaceholder(0) - layout_args.thread_bounds->min);
864	    auto rep = inv->Forward(fwd).back();
865	    AddPredicate(EQ(rep, 0));
866	  }
867	}
868	Fragment
869	ParallelOpNode::ChooseBestCandidate(const Fragment &candidate_from_buffer,
870	                                    const Fragment &candidate_from_plan,
871	                                    const LayoutInferArgs &layout_args) const {
872	  // Strategy overview:
873	  // 1) Validate each candidate against all known source fragments. If only one
874	  //    is compatible, choose it immediately.
875	  // 2) If both are compatible, compare their containment relation:
876	  //      - If buffer-based contains plan-based, prefer plan (usually smaller
877	  //      rep).
878	  //      - If plan-based contains buffer-based, prefer buffer.
879	  // 3) If neither contains the other, prefer the one with provably smaller or
880	  //    equal replication extent; otherwise fall back to buffer-based candidate.
881	  // Note: Final global validation happens after selection elsewhere.
882	  auto vars =
883	      loop_vars_.Map([](const IterVar &iv) { return PrimExpr(iv->var); });
884	  auto contains = [&](const Fragment &big, const Fragment &small) {
885	    // contains(A, B) means: for any loop index, the threads that access
886	    // B's elements are a subset of those that access A's elements.
887	    return ProveFragmentContains(small, big, vars, vars, analyzer_);
888	  };
889	
890	  bool buf_ok =
891	      ValidateCandidateAgainstFragments(candidate_from_buffer, layout_args);
892	  bool plan_ok =
893	      ValidateCandidateAgainstFragments(candidate_from_plan, layout_args);
894	
895	  if (buf_ok && !plan_ok) {
896	    DLOG(INFO)
897	        << "[FreeInfer] prefer compute_from_buffer (only valid candidate).";
898	    return candidate_from_buffer;
899	  }
900	  if (plan_ok && !buf_ok) {
901	    DLOG(INFO)
902	        << "[FreeInfer] prefer PlanLoopPartition (only valid candidate).";
903	    return candidate_from_plan;
904	  }
905	  if (!(buf_ok && plan_ok)) {
906	    // Both invalid here; let the caller continue to final validation/throw.
907	    // Returning buffer-based candidate keeps behavior deterministic.
908	    return candidate_from_buffer; // arbitrary; caller will catch later
909	  }
910	
911	  // Both candidates may be semantically valid for reads from a fully
912	  // replicated fragment.  The plan candidate often minimizes replication by
913	  // assigning one logical element to each CUDA thread, but that can turn a
914	  // register fragment access into `fragment[threadIdx.x]`.  CUDA cannot keep a
915	  // register array with runtime indexing in scalar registers, so this shape
916	  // spills the whole fragment to local memory before the final store.
917	  //
918	  // When this parallel loop publishes data to shared/global memory, prefer the
919	  // valid candidate that keeps fragment physical indices independent of the
920	  // thread variable.  For a fully replicated readback this selects the
921	  // fragment-derived layout, and BuildReplicationGuardsIfNeeded then emits the
922	  // single-replica guard (e.g. `threadIdx.x == 0`) to avoid duplicate stores.
923	  // Fragment-only loops keep the old containment/replication heuristic below.
924	  if (!store_shared_global_buffers_.empty()) {
925	    bool buf_thread_index =
926	        HasThreadDependentFragmentIndex(candidate_from_buffer, layout_args);
927	    bool plan_thread_index =
928	        HasThreadDependentFragmentIndex(candidate_from_plan, layout_args);
929	    if (buf_thread_index != plan_thread_index) {
930	      return buf_thread_index ? candidate_from_plan : candidate_from_buffer;
931	    }
932	  }
933	
934	  bool buf_contains_plan = contains(candidate_from_buffer, candidate_from_plan);
935	  bool plan_contains_buf = contains(candidate_from_plan, candidate_from_buffer);
936	
937	  auto rep_buf = candidate_from_buffer->ReplicateExtent();
938	  auto rep_plan = candidate_from_plan->ReplicateExtent();
939	
940	  // Prefer the contained candidate (tends to minimize replication while
941	  // respecting access coverage):
942	  if (buf_contains_plan && !plan_contains_buf) {
943	    return candidate_from_plan;
944	  }
945	  if (plan_contains_buf && !buf_contains_plan) {
946	    return candidate_from_buffer;
947	  }
948	  // Neither strictly contains the other; prefer the one with smaller/equal rep.
949	  if (analyzer_.CanProve(rep_plan <= rep_buf)) {
950	    return candidate_from_plan;
951	  }
952	  // Safe fallback: buffer-based candidate is always correct.
953	  return candidate_from_buffer;
954	}
955	
956	bool ParallelOpNode::HasThreadDependentFragmentIndex(
957	    const Fragment &candidate, const LayoutInferArgs &layout_args) const {
958	  // Mirror the index substitution that PartitionLoop would apply for this
959	  // candidate without actually rebuilding the loop.  We create symbolic output
960	  // coordinates plus a symbolic thread variable, invert the candidate layout
961	  // back to the original loop variables, and then apply each known fragment
962	  // layout's Forward() map.  If any resulting physical fragment index still
963	  // contains the symbolic thread variable, lowering this candidate would emit a
964	  // runtime-thread-indexed register array access such as
965	  // `fragment[threadIdx.x]`.
966	  if (!candidate.defined()) {
967	    return false;
968	  }
969	
970	  int old_loop_depth = static_cast<int>(loop_vars_.size());
971	  if (candidate->InputDim() != static_cast<size_t>(old_loop_depth)) {
972	    return false;
973	  }
974	
975	  Var thread_var("__tl_candidate_thread");
976	  Array<PrimExpr> partition_vars;
977	  for (size_t i = 0; i < candidate->OutputDim(); ++i) {
978	    partition_vars.push_back(Var("__tl_candidate_i" + std::to_string(i)));
979	  }
980	  partition_vars.push_back(thread_var);
981	
982	  auto inv_loop = candidate->InverseWithLevel().first;
983	  Array<PrimExpr> recovered_indices = inv_loop->Forward(partition_vars);
984	
985	  Map<Var, PrimExpr> loop_var_map;
986	  for (int i = 0; i < old_loop_depth; ++i) {
987	    loop_var_map.Set(loop_vars_[i]->var, recovered_indices[i]);
988	  }
989	
990	  Map<Var, PrimExpr> thread_offset_map;
991	  bool has_thread_offset = false;
992	  if (candidate->ThreadRange().defined()) {
993	    auto range = candidate->ThreadRange();
994	    thread_offset_map.Set(thread_var, thread_var - range->min);
995	    has_thread_offset = true;
996	  }
997	
998	  auto uses_thread_var = [&](const PrimExpr &expr) {
999	    PrimExpr simplified = analyzer_.Simplify(expr);
1000	    return tirx::UsesVar(simplified, [&](const VarNode *var_node) {
1001	      return GetRef<Var>(var_node).same_as(thread_var);
1002	    });
1003	  };
1004	
1005	  for (const auto &buffer : access_order_) {
1006	    if (!IsFragmentBuffer(buffer) || !layout_args.layout_map.count(buffer)) {
1007	      continue;
1008	    }
1009	    auto fragment_layout = layout_args.layout_map[buffer].as<Fragment>();
1010	    if (!fragment_layout.has_value()) {
1011	      continue;
1012	    }
1013	
1014	    Array<PrimExpr> indices = GetAccessInfo(buffer).indices.Map(
1015	        [&](const PrimExpr &index) { return Substitute(index, loop_var_map); });
1016	    if (has_thread_offset) {
1017	      indices = Substitute(indices, thread_offset_map);
1018	    }
1019	
1020	    Array<PrimExpr> physical_indices =
1021	        fragment_layout.value()->Forward(indices);
1022	    for (const auto &index : physical_indices) {
1023	      if (uses_thread_var(index)) {
1024	        return true;
1025	      }
1026	    }
1027	  }
1028	
1029	  return false;
1030	}
1031	
1032	} // namespace tl
1033	} // namespace tvm
